"""Emit packed original rows followed by oriented placements generated by check_h5_p7_direct_placements.py."""
from pathlib import Path
import sys
from h5_three_sink_leak_sets import CASES, EDGES, N

index = int(sys.argv[1])
rows = (*EDGES, *N)
wanted = (1 << len(EDGES)) - 1
for j in CASES[index]:
    wanted |= 1 << (len(EDGES) + j)
print(wanted)
print(*(sum(1 << k for k, row in enumerate(rows) if row & v) for v in range(1024)))
print(Path(f'/tmp/h5-p7-physical-{index}.txt').read_text(), end='')
